function whatsappUrl(d){return 'https://wa.me/'+CONTACT_WHATSAPP+'?text='+encodeURIComponent(d.whatsappMessage)}function whatsappIcon(){return '<svg class="whatsapp-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false"><path d="M20.4 11.8a8.4 8.4 0 0 1-12.5 7.3L3 20.5l1.4-4.8a8.4 8.4 0 1 1 16-3.9Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><path d="M8.7 7.4c-.2-.5-.4-.5-.7-.5h-.5c-.3 0-.6.2-.8.5-.4.5-.7 1.1-.6 1.8.1 2.4 3.6 6.2 6.5 7 .7.2 1.5.1 2.1-.2.5-.3 1.1-1 1.1-1.4l-.1-.6-2.2-1.1c-.3-.1-.5-.1-.7.2l-.8.9c-.2.2-.4.2-.7.1a7 7 0 0 1-3.2-2.9c-.2-.3-.1-.4.1-.6l.7-.8c.2-.2.2-.4.1-.7l-.8-1.7Z" fill="currentColor"/></svg>'}function floatingWhatsapp(d){return `<a class="whatsapp-floating" href="${whatsappUrl(d)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(d.whatsappCta)}">${whatsappIcon()}<span class="whatsapp-tooltip">${d.whatsappCta}</span></a>`}function menuLinks(d){return `<a href="${homeUrl(lang)}">${d.backHome}</a>${d.nav.map((x,i)=>link(x,ids[i])+(i===0?link(d.ratesNav,'offers'):'' )).join('')}<a href="${exportRoot.href}${lang}/blog/" ${location.pathname.includes('/blog')?'aria-current="page"':''}>Blog</a>${link(d.talk,'contact','btn')}`}function languageLinks(d){return `<div class="language-links" aria-label="${d.select}">${['fr','pt','es'].map(x=>`<a href="${location.pathname.includes('/blog')?new URL(`${x}/blog/`,exportRoot).href:location.pathname.includes('/outil-communication/')?new URL(`${x}/outil-communication/`,exportRoot).href:homeUrl(x)}" hreflang="${LOCALES[x]}" lang="${LOCALES[x]}" ${x===lang?'aria-current="true"':''}>${x.toUpperCase()}</a>`).join('')}</div>`}
